                            <li>Isso garante que você tenha total portabilidade dos seus dados sem precisar de servidores externos.</li>
                        </ul>
                    </div>
                </Card>
            )}

            {/* 9. PAST ASSEMBLIES */}
            {activeTab === 'past_assemblies' && (
